import { IIntegrationMapSyncRepository, IOrganizationGithubRepository } from '@gauzy/contracts';
import { Body, Controller, Param, Post, Put, UsePipes, ValidationPipe } from '@nestjs/common';
import { UUIDValidationPipe } from 'shared/pipes';
import { GithubRepositoryService } from './github-repository.service';
import { UpdateGithubRepositoryDTO } from './dto';

@Controller('repository')
export class GitHubRepositoryController {

    constructor(
        private readonly _githubRepositoryService: GithubRepositoryService
    ) { }

    /**
     * Sync a GitHub repository with Gauzy using provided data.
     *
     * @param entity The data needed for synchronization.
     * @returns The synchronized integration map.
     */
    @Post('/sync')
    async syncRepository(
        @Body() entity: IIntegrationMapSyncRepository,
    ): Promise<IOrganizationGithubRepository> {
        try {
            return await this._githubRepositoryService.syncGithubRepository(entity);
        } catch (error) {
            // Handle errors, e.g., return an error response.
            throw new Error('Failed to sync GitHub repository');
        }
    }

    /**
     * Handle an HTTP PUT request to update a GitHub repository by its unique identifier.
     * @param id - A string representing the unique identifier of the GitHub repository.
     * @param input - An object representing the data to update the GitHub repository with.
     * @returns A Promise that resolves to the updated GitHub repository data.
     */
    @Put('/:id')
    @UsePipes(new ValidationPipe({ whitelist: true }))
    async update(
        @Param('id', UUIDValidationPipe) id: string,
        @Body() input: UpdateGithubRepositoryDTO,
    ): Promise<IOrganizationGithubRepository> {
        try {
            // Ensure that a GitHub repository with the provided identifier exists.
            await this._githubRepositoryService.findOneByIdString(id);

            // Attempt to update the GitHub repository using the provided data.
            return await this._githubRepositoryService.create({
                ...input,
                id
            });
        } catch (error) {
            // Handle errors, e.g., return an error response.
            throw new Error('Failed to update GitHub repository fields');
        }
    }
}

import { HttpException, HttpStatus, Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { CommandBus } from '@nestjs/cqrs';
import { Repository } from 'typeorm';
import { IIntegrationMapSyncRepository, IOrganizationGithubRepository } from '@gauzy/contracts';
import { TenantAwareCrudService } from 'core/crud';
import { OrganizationGithubRepository } from './github-repository.entity';
import { IntegrationSyncGithubRepositoryCommand } from '../commands';

@Injectable()
export class GithubRepositoryService extends TenantAwareCrudService<OrganizationGithubRepository> {
    private readonly logger = new Logger('GithubRepositoryService');

    constructor(
        private readonly _commandBus: CommandBus,

        @InjectRepository(OrganizationGithubRepository)
        private readonly organizationGithubRepository: Repository<OrganizationGithubRepository>
    ) {
        super(organizationGithubRepository);
    }

    /**
     * Synchronize a GitHub repository with an integration.
     *
     * @param input - The input data for synchronization.
     * @returns An object indicating success or failure of the synchronization.
     */
    async syncGithubRepository(
        input: IIntegrationMapSyncRepository
    ): Promise<IOrganizationGithubRepository> {
        try {
            return await this._commandBus.execute(
                new IntegrationSyncGithubRepositoryCommand(
                    input
                )
            );
        } catch (error) {
            // Handle errors and return an appropriate error response
            this.logger.error('Error while sync github integration repository', error.message);
            throw new HttpException(`Failed to sync GitHub repository: ${error.message}`, HttpStatus.BAD_REQUEST);
        }
    }
}

import { QueryBus } from '@nestjs/cqrs';
import {
	Controller,
	Get,
	HttpCode,
	HttpStatus,
	Query,
	UseGuards,
	UsePipes,
