import {
	Controller,
	UseGuards,
	HttpStatus,
	Get,
	Query,
	Post,
	Body,
	ValidationPipe,
	UsePipes
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse } from '@nestjs/swagger';
import { IGetActivitiesInput, IBulkActivitiesInput, ReportGroupFilterEnum, PermissionsEnum } from '@gauzy/contracts';
import { PermissionGuard, TenantPermissionGuard } from './../../shared/guards';
import { Permissions } from './../../shared/decorators';
import { ActivityService } from './activity.service';
import { ActivityMapService } from './activity.map.service';
import { ActivityQueryDTO } from './dto/query';

@ApiTags('Activity')
@UseGuards(TenantPermissionGuard, PermissionGuard)
@Permissions(PermissionsEnum.TIME_TRACKER, PermissionsEnum.TIMESHEET_EDIT_TIME)
@Controller()
export class ActivityController {

	constructor(
		private readonly activityService: ActivityService,
		private readonly activityMapService: ActivityMapService
	) {}

	@ApiOperation({ summary: 'Get Activities' })
	@ApiResponse({
		status: HttpStatus.BAD_REQUEST,
		description: 'Invalid input, The response body may contain clues as to what went wrong'
	})
	@Get()
	@UsePipes(new ValidationPipe({ transform: true, whitelist: true }))
	async getActivities(
		@Query() options: ActivityQueryDTO
	) {
		const defaultParams: Partial<IGetActivitiesInput> = {
			page: 0,
			limit: 30
		};
		options = Object.assign({}, defaultParams, options);
		return await this.activityService.getActivities(options);
	}

	@ApiOperation({ summary: 'Get Daily Activities' })
	@ApiResponse({
		status: HttpStatus.BAD_REQUEST,
		description: 'Invalid input, The response body may contain clues as to what went wrong'
	})
	@Get('daily')
	@UsePipes(new ValidationPipe({ transform: true, whitelist: true }))
	async getDailyActivities(
		@Query() options: ActivityQueryDTO
	) {
		return await this.activityService.getDailyActivities(options);
	}

	@ApiOperation({ summary: 'Get Daily Activities' })
	@ApiResponse({
		status: HttpStatus.BAD_REQUEST,
		description:
			'Invalid input, The response body may contain clues as to what went wrong'
	})
	@Get('report')
	@UsePipes(new ValidationPipe({ transform: true, whitelist: true }))
	async getDailyActivitiesReport(
		@Query() options: ActivityQueryDTO
	) {
		let activities = await this.activityService.getDailyActivitiesReport(options);
		if (options.groupBy === ReportGroupFilterEnum.date) {
			activities = this.activityMapService.mapByDate(activities);
		} else if (options.groupBy === ReportGroupFilterEnum.employee) {
			activities = this.activityMapService.mapByEmployee(activities);
		} else if (options.groupBy === ReportGroupFilterEnum.project) {
			activities = this.activityMapService.mapByProject(activities);
		}
		return activities;
	}

	@ApiOperation({ summary: 'Save bulk Activities' })
	@ApiResponse({
		status: HttpStatus.BAD_REQUEST,
		description:
			'Invalid input, The response body may contain clues as to what went wrong'
	})
	@Post('bulk')
	async bulkSaveActivities(
		@Body() entities: IBulkActivitiesInput
	) {
		return await this.activityService.bulkSave(entities);
	}
}

import { IActivity } from '@gauzy/contracts';
import { Injectable } from '@nestjs/common';
import * as moment from 'moment';
import { chain } from 'underscore';

@Injectable()
export class ActivityMapService {
	constructor() {}

	mapByDate(activities: IActivity[]) {
		const dailyLogs: any = this.groupByDate(activities).map(
			(byDateActivity: IActivity[], date) => {
				const sum = this.getDurationSum(byDateActivity);
				const byEmployee = this.groupByEmployee(byDateActivity).map(
					(byEmployeeActivity: IActivity[]) => {
						const byProject = this.groupByProject(
							byEmployeeActivity
						).map((byProjectActivity: IActivity[]) => {
							const project =
								byProjectActivity.length > 0 &&
								byProjectActivity[0]
									? byProjectActivity[0].project
									: null;

							return {
								project,
								activity: byProjectActivity.map((row) =>
									this.mapActivitiesPercentage(row, sum)
								)
							};
						}).value();

						const employee =
							byEmployeeActivity.length > 0 &&
							byEmployeeActivity[0]
								? byEmployeeActivity[0].employee
								: null;
						return {
							employee,
							projects: byProject
						};
					}
				).value();

				return {
					date,
					employees: byEmployee
				};
			}
		).value();
		return dailyLogs;
	}

	mapByEmployee(activities: IActivity[]) {
		const byEmployee: any = this.groupByEmployee(activities).map(
			(byEmployeeActivity: IActivity[]) => {
				const sum = this.getDurationSum(byEmployeeActivity);
				const dailyLogs = this.groupByDate(byEmployeeActivity).map(
					(byDateActivity: IActivity[], date) => {
						const byProject = this.groupByProject(
							byDateActivity
						).map((byProjectActivity: IActivity[]) => {
							const project =
								byProjectActivity.length > 0 &&
								byProjectActivity[0]
									? byProjectActivity[0].project
									: null;
							return {
								project,
								activity: byProjectActivity.map((row) =>
									this.mapActivitiesPercentage(row, sum)
								)
							};
						}).value();

						return {
							date,
							projects: byProject
						};
					}
				).value();

				const employee =
					byEmployeeActivity.length > 0 && byEmployeeActivity[0]
						? byEmployeeActivity[0].employee
						: null;
				return {
					employee,
					dates: dailyLogs
				};
			}
		).value();
		return byEmployee;
	}

	mapByProject(activities: IActivity[]) {
		const byEmployee: any = this.groupByProject(activities).map(
			(byProjectActivity: IActivity[]) => {
				const sum = this.getDurationSum(byProjectActivity);

				const dailyLogs = this.groupByDate(byProjectActivity).map(
					(byDateActivity: IActivity[], date) => {
						const byProject = this.groupByEmployee(
							byDateActivity
						).map((byEmployeeActivity: IActivity[]) => {
							const employee =
								byEmployeeActivity.length > 0 &&
								byEmployeeActivity[0]
									? byEmployeeActivity[0].employee
									: null;
							return {
								employee,
								activity: byEmployeeActivity.map((row) =>
									this.mapActivitiesPercentage(row, sum)
								)
							};
						}).value();

						return {
							date,
							employees: byProject
						};
					}
				).value();

				const project =
					byProjectActivity.length > 0 && byProjectActivity[0]
						? byProjectActivity[0].project
						: null;
				return {
					project,
					dates: dailyLogs
				};
			}
		).value();
		return byEmployee;
	}

	private groupByProject(activities: IActivity[]) {
		return chain(activities).groupBy((activity) => {
			return activity.projectId;
		});
	}

	private groupByDate(activities: IActivity[]) {
		return chain(activities).groupBy((activity) => {
			return moment.utc(activity.date).format('YYYY-MM-DD');
		});
	}

	private groupByEmployee(activities: IActivity[]) {
		return chain(activities).groupBy((activity) => {
			return activity.employeeId;
		});
	}

	private mapActivitiesPercentage(activity, sum = 0) {
		activity.duration_percentage = (((parseInt(activity.duration, 10) * 100) / sum).toFixed(2)) || 0;
		return activity;
	}

	private getDurationSum(activities) {
		return activities.reduce((iteratee: any, log: any) => {
			return iteratee + parseInt(log.duration, 10);
		}, 0);
	}
}

